/* ---------- carnet partagé du foyer (Maisonnée) ---------- */
// Reference copy for merging, kept PER OPEN COPY of the Carnet (read once from the phone's storage at start).
// Two copies open at once in the same browser (a tab, Maisonnée's background Carnet) used to share it,
// each then believed its own week was the newer one and they kept overwriting each other.
let cloudBase=LS.get("cm_cloud_base",null), cloudPh=LS.get("cm_cloud_ph","");
const stateUid=()=>cloud.owner||cloud.user.id;
// menu.mzBase is this copy's own bookmark for the Maisonnée bridge (what its week and Maisonnée's meals last agreed on).
// It never travels: mixed with another copy's bookmark it made the bridge undo or delete meals.
const noMz=m=>{const o=Object.assign({},m||{});delete o.mzBase;return o;};
const shareMenu=()=>noMz(menu);
const sharedCarnet=()=>!!(cloud.owner&&cloud.user&&cloud.owner!==cloud.user.id);
// favourites, chosen photos… of recipes this phone does not have (yet): kept as they are, never dropped from the shared carnet
