/* V9.6 — Réception rapide des changements du carnet partagé.
   Le canal ne transporte pas les courses : il déclenche une relecture du serveur.
   Le contrôle périodique existant reste le repli si Realtime n'est pas activé. */
let cm96Channel=null,cm96Timer=null,cm96Syncing=false,cm96Pending=false;
function cm96StopRealtime(){
  clearTimeout(cm96Timer);cm96Timer=null;cm96Pending=false;
  if(cm96Channel&&cloud.sb){try{cloud.sb.removeChannel(cm96Channel);}catch(e){}}
  cm96Channel=null;
}
function cm96StartRealtime(){
  cm96StopRealtime();
  if(!cloudOn()||!cloud.sb)return;
  const owner=stateUid();
  cm96Channel=cloud.sb.channel('cm-courses-v96-'+owner)
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'user_state',filter:'user_id=eq.'+owner},event=>{
      const at=event.new&&event.new.updated_at;
      if(at&&at===stateSeen)return; // notre propre écriture ou déjà traitée
      cm96Pending=true;
      if(document.visibilityState==='visible')cm96Schedule();
    }).subscribe();
}
function cm96Schedule(){
  if(cm96Timer||!cm96Pending||!cloudOn()||document.visibilityState!=='visible')return;
  cm96Timer=setTimeout(async()=>{
    cm96Timer=null;
    if(cm96Syncing||cloud.busy){cm96Schedule();return;}
    cm96Pending=false;cm96Syncing=true;
    try{
      const before=new Set(shopping().filter(x=>!menu.checked[x.key]).map(x=>x.key));
      await cloudSync();
      const added=shopping().filter(x=>!menu.checked[x.key]&&!before.has(x.key));
      if(added.length){
        toast(added.length+' nouvel'+(added.length>1?'s':'')+' article'+(added.length>1?'s':'')+' dans les courses');
        try{if(window.parent!==window)window.parent.postMessage({type:'cm-courses-v96-new',count:added.length},location.origin);}catch(e){}
      }
    }catch(e){}finally{cm96Syncing=false;if(cm96Pending)cm96Schedule();}
  },450);
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cm96Pending)cm96Schedule();});
