async function cloudMigrate(){if(!cloud.admin)return;const sb=cloud.sb;toast("⏳ Vérification de la base commune…");
  // what is really in the common book (not what this phone believes)
  const exist=new Map();let f=0;for(;;){const{data,error}=await sb.from("recipes").select("legacy_id,author_id").range(f,f+999);if(error){toast("Base inaccessible : "+error.message);return;}(data||[]).forEach(x=>exist.set(x.legacy_id,x.author_id));if(!data||data.length<1000)break;f+=1000;}
  let fixed=0;for(const[id,r]of Object.entries(recipes))if(exist.has(id)&&!r.cloudAuthor){r.cloudAuthor=exist.get(id);fixed++;}
  if(fixed)LS.set("cm_recipes",recipes);
  const todo=Object.keys(recipes).filter(id=>!recipes[id].shared&&!exist.has(id));
  if(!todo.length){cloud.msg=`✓ Tout est déjà dans la base commune (${exist.size} recettes).`;toast(cloud.msg);renderAcct();return;}
  if(!confirm(`${todo.length} recette${todo.length>1?"s":""} de ce téléphone ne ${todo.length>1?"sont":"est"} pas encore dans la base commune. Les envoyer à votre nom ?`))return;
  const H=LS.get("cm_cloudhash",{});todo.forEach(id=>{delete H[id];delete recipes[id].cloudAuthor;});H.__all=1;LS.set("cm_cloudhash",H);toast("⏳ Envoi des recettes…");
  await cloudPush();const H2=LS.get("cm_cloudhash",{});delete H2.__all;LS.set("cm_cloudhash",H2);
  const{count}=await sb.from("recipes").select("id",{count:"exact",head:true});const err=cloud.lastErr||[];
  cloud.msg=`Base commune : ${count??"?"} recettes · ${cloud.lastSent||0} envoyées maintenant`+(err.length?` · ${err.length} refusée${err.length>1?"s":""} (${err.slice(0,3).join(" ; ")})`:"");
  toast(err.length?"Envoi terminé avec des erreurs (voir Mon compte)":`✓ ${count} recettes dans la base commune`);renderAcct();}
async function loadMembers(){const{data,error}=await cloud.sb.rpc("admin_members");cloud.members=error?[]:data;if(error)toast("Liste impossible : "+error.message);$("#memList").innerHTML=membersHtml();}
function membersHtml(){const l=cloud.members;if(!l)return"";if(!l.length)return`<p class="muted">Aucun membre.</p>`;
  const S={pending:"⏳ en attente",active:"✅ actif",blocked:"⛔ bloqué"};
  return l.map(m=>`<div class="mem"><div><b>${esc(m.pseudo)}</b>${m.role==="admin"?" 👑":""} <span class="muted">· ${S[m.status]||m.status}</span><br><small class="muted">${esc(m.email||"")} · inscrit le ${new Date(m.created_at).toLocaleDateString("fr-FR")}${m.last_seen?" · vu "+ago(Date.parse(m.last_seen)):""} · ${m.recipes_count} recette${m.recipes_count>1?"s":""}</small></div>
    ${m.id===cloud.user.id?"":`<div class="row" style="gap:6px">${m.status!=="active"?`<button type="button" class="btn primary" data-act="memSet" data-id="${m.id}" data-s="active">Valider</button>`:`<button type="button" class="btn" data-act="memSet" data-id="${m.id}" data-s="blocked">Bloquer</button>`}${m.status==="active"?(m.role==="admin"?`<button type="button" class="btn ghost" data-act="memSet" data-id="${m.id}" data-s="active" data-r="member">Retirer admin</button>`:`<button type="button" class="btn ghost" data-act="memSet" data-id="${m.id}" data-s="active" data-r="admin">Rendre admin</button>`):""}</div>`}</div>`).join("");}
