const PACKS={"sushi1":{"sushi-au-saumon": {"name": "Sushi au saumon", "cat": "Entrée", "cats": ["Plat"], "serves": 4, "time": 75, "tags": [], "ing": [{"q": 300, "u": "g", "n": "riz à sushi", "r": "Épicerie"}, {"q": 5, "u": "c. à s.", "n": "vinaigre de riz", "r": "Épicerie"}, {"q": 1, "u": "c. à s.", "n": "sucre", "r": "Épicerie"}, {"q": 1, "u": "c. à c.", "n": "sel", "r": "Épicerie"}, {"q": 300, "u": "g", "n": "saumon frais extra-frais (qualité sashimi)", "r": "Boucherie & poisson"}, {"q": 1, "u": "c. à c.", "n": "wasabi", "r": "Épicerie"}, {"q": 1, "u": "pièce", "n": "sauce soja (flacon)", "r": "Épicerie"}, {"q": 1, "u": "pièce", "n": "gingembre mariné (pot)", "r": "Épicerie"}], "steps": "Rincez le riz à sushi dans un saladier d'eau froide en le frottant doucement entre vos mains, videz l'eau trouble et recommencez 4 à 5 fois, jusqu'à ce que l'eau reste presque claire. Égouttez 15 min dans une passoire.\nMettez le riz dans une casserole avec son volume d'eau froide plus 10 % (pour 300 g de riz : 33 cl d'eau). Couvrez, portez à ébullition à feu vif (8/9), puis baissez à feu doux (2/9) et cuisez 12 min sans soulever le couvercle. Éteignez et laissez reposer 10 min, toujours couvert.\nPendant ce temps, mélangez le vinaigre de riz, le sucre et le sel dans un bol jusqu'à ce qu'ils fondent (passez 20 secondes au micro-ondes si besoin).\nÉtalez le riz chaud dans un grand plat. Versez le vinaigre en pluie et mélangez en « coupant » le riz avec une spatule (sans l'écraser), en l'éventant pour le faire refroidir et briller. Couvrez d'un torchon humide : il doit être à température ambiante avant de l'utiliser.\nCoupez le saumon (sans peau ni arêtes) en tranches de 5 mm d'épaisseur, en biais, de la taille d'un doigt (7 × 2,5 cm). Gardez-le au frais jusqu'au dernier moment.\nPréparez un bol d'eau froide avec un trait de vinaigre de riz : mouillez-vous les mains avant chaque sushi pour que le riz ne colle pas.\nPrenez 20 g de riz (une grosse noix) et formez une petite boule allongée en la pressant doucement dans le creux de la main : elle doit tenir sans être tassée.\nPosez une pointe de wasabi sur une tranche de saumon, posez la boulette de riz dessus et pressez légèrement avec deux doigts pour que le poisson épouse le riz. Retournez : le saumon dessus.\nServez aussitôt avec la sauce soja, le gingembre mariné et un peu de wasabi. Trempez le côté poisson (pas le riz) dans la sauce soja."}, "maki-au-saumon": {"name": "Maki au saumon", "cat": "Entrée", "cats": ["Plat"], "serves": 4, "time": 75, "tags": [], "ing": [{"q": 300, "u": "g", "n": "riz à sushi", "r": "Épicerie"}, {"q": 5, "u": "c. à s.", "n": "vinaigre de riz", "r": "Épicerie"}, {"q": 1, "u": "c. à s.", "n": "sucre", "r": "Épicerie"}, {"q": 1, "u": "c. à c.", "n": "sel", "r": "Épicerie"}, {"q": 250, "u": "g", "n": "saumon frais extra-frais (qualité sashimi)", "r": "Boucherie & poisson"}, {"q": 4, "u": "pièce", "n": "feuilles d'algue nori", "r": "Épicerie"}, {"q": 1, "u": "c. à c.", "n": "wasabi", "r": "Épicerie"}, {"q": 1, "u": "pièce", "n": "sauce soja (flacon)", "r": "Épicerie"}], "steps": "Rincez le riz à sushi dans un saladier d'eau froide en le frottant doucement entre vos mains, videz l'eau trouble et recommencez 4 à 5 fois, jusqu'à ce que l'eau reste presque claire. Égouttez 15 min dans une passoire.\nMettez le riz dans une casserole avec son volume d'eau froide plus 10 % (pour 300 g de riz : 33 cl d'eau). Couvrez, portez à ébullition à feu vif (8/9), puis baissez à feu doux (2/9) et cuisez 12 min sans soulever le couvercle. Éteignez et laissez reposer 10 min, toujours couvert.\nPendant ce temps, mélangez le vinaigre de riz, le sucre et le sel dans un bol jusqu'à ce qu'ils fondent (passez 20 secondes au micro-ondes si besoin).\nÉtalez le riz chaud dans un grand plat. Versez le vinaigre en pluie et mélangez en « coupant » le riz avec une spatule (sans l'écraser), en l'éventant pour le faire refroidir et briller. Couvrez d'un torchon humide : il doit être à température ambiante avant de l'utiliser.\nCoupez le saumon en bâtonnets de 1 cm de côté, de la longueur de la feuille.\nCoupez chaque feuille de nori en deux dans la largeur. Posez une demi-feuille sur la natte de bambou (couverte de film alimentaire), face brillante en dessous, le long côté vers vous.\nLes mains mouillées, étalez une fine couche de riz (environ 90 g) sur la feuille en laissant 1 cm libre en haut. Ne tassez pas.\nTracez un trait de wasabi au milieu du riz et posez un bâtonnet de saumon dessus.\nSoulevez le bord de la natte et roulez en serrant fermement avec les doigts pour que la garniture reste au centre, jusqu'à la bande libre. Mouillez-la légèrement pour coller. Pressez le rouleau dans la natte pour le rendre bien rond.\nAvec un couteau bien aiguisé et mouillé, coupez chaque rouleau en deux, puis chaque moitié en 3 : 6 makis par rouleau. Essuyez et remouillez la lame entre chaque coupe.\nServez avec la sauce soja et le wasabi."}, "futomakis-avocat-concombre-gambas": {"name": "Futomakis avocat, concombre et gambas", "cat": "Entrée", "cats": ["Plat"], "serves": 4, "time": 80, "tags": [], "ing": [{"q": 300, "u": "g", "n": "riz à sushi", "r": "Épicerie"}, {"q": 5, "u": "c. à s.", "n": "vinaigre de riz", "r": "Épicerie"}, {"q": 1, "u": "c. à s.", "n": "sucre", "r": "Épicerie"}, {"q": 1, "u": "c. à c.", "n": "sel", "r": "Épicerie"}, {"q": 8, "u": "pièce", "n": "gambas crues", "r": "Boucherie & poisson"}, {"q": 1, "u": "pièce", "n": "avocat mûr", "r": "Fruits & légumes"}, {"q": 0.5, "u": "pièce", "n": "concombre", "r": "Fruits & légumes"}, {"q": 4, "u": "pièce", "n": "feuilles d'algue nori", "r": "Épicerie"}, {"q": 1, "u": "c. à s.", "n": "mayonnaise", "r": "Épicerie"}, {"q": 1, "u": "pièce", "n": "citron vert", "r": "Fruits & légumes"}, {"q": 1, "u": "pièce", "n": "sauce soja (flacon)", "r": "Épicerie"}], "steps": "Rincez le riz à sushi dans un saladier d'eau froide en le frottant doucement entre vos mains, videz l'eau trouble et recommencez 4 à 5 fois, jusqu'à ce que l'eau reste presque claire. Égouttez 15 min dans une passoire.\nMettez le riz dans une casserole avec son volume d'eau froide plus 10 % (pour 300 g de riz : 33 cl d'eau). Couvrez, portez à ébullition à feu vif (8/9), puis baissez à feu doux (2/9) et cuisez 12 min sans soulever le couvercle. Éteignez et laissez reposer 10 min, toujours couvert.\nPendant ce temps, mélangez le vinaigre de riz, le sucre et le sel dans un bol jusqu'à ce qu'ils fondent (passez 20 secondes au micro-ondes si besoin).\nÉtalez le riz chaud dans un grand plat. Versez le vinaigre en pluie et mélangez en « coupant » le riz avec une spatule (sans l'écraser), en l'éventant pour le faire refroidir et briller. Couvrez d'un torchon humide : il doit être à température ambiante avant de l'utiliser.\nDécortiquez les gambas en gardant la queue si vous voulez, retirez le filament noir du dos. Plongez-les 2 min dans de l'eau bouillante salée : elles deviennent roses. Refroidissez-les dans l'eau froide, retirez la queue et coupez-les en deux dans la longueur.\nCoupez l'avocat en deux, retirez le noyau, pelez-le et coupez-le en lamelles ; arrosez de jus de citron vert pour qu'il ne noircisse pas. Coupez le concombre en bâtonnets de 1 cm sans les graines.\nPosez une feuille de nori entière sur la natte (couverte de film), face brillante en dessous. Les mains mouillées, étalez une couche de riz (environ 120 g) en laissant 2 cm libres en haut.\nAu milieu du riz, alignez les gambas, l'avocat et le concombre, et ajoutez un petit trait de mayonnaise. Ne mettez pas trop de garniture, sinon le rouleau ne fermera pas.\nRoulez en serrant avec la natte jusqu'à la bande libre, mouillez-la pour coller, puis pressez le rouleau pour le rendre régulier. Laissez reposer 5 min, collure en dessous.\nCoupez chaque futomaki en 8 tranches avec un couteau mouillé, en essuyant la lame entre chaque coupe. Servez avec la sauce soja."}},"sante1":{"ratatouille": {"name": "Ratatouille", "cat": "Végé", "serves": 4, "time": 60, "tags": ["legumes", "reequilibrage", "lowcarb"], "light": true, "ing": [{"n": "aubergines", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "courgettes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "poivrons", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "gousses d'ail", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "herbes de Provence", "q": 1, "u": "c. à s.", "r": "Épicerie"}, {"n": "huile d'olive", "q": 3, "u": "c. à s.", "r": "Épicerie"}], "steps": "Couper tous les légumes en dés.\nFaire revenir oignons et ail dans l'huile, puis les poivrons 5 min.\nAjouter aubergines et courgettes, 10 min, puis tomates et herbes.\nMijoter 35 min à couvert. Servir chaud ou froid, avec un œuf au plat si besoin."}, "tian-provencal": {"name": "Tian provençal", "cat": "Végé", "serves": 4, "time": 60, "tags": ["legumes", "lowcarb"], "light": true, "ing": [{"n": "courgettes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "aubergines", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "gousses d'ail", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "thym", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "huile d'olive", "q": 3, "u": "c. à s.", "r": "Épicerie"}, {"n": "feta", "q": 100, "u": "g", "r": "Crémerie"}], "steps": "Émincer l'oignon et l'étaler au fond d'un plat avec l'ail.\nCouper les légumes en rondelles fines et les alterner debout dans le plat.\nArroser d'huile, parsemer de thym, saler, poivrer.\nCuire 45 min à 180 °C, émietter la feta 10 min avant la fin."}, "veloute-brocoli": {"name": "Velouté de brocoli", "cat": "Soupe", "serves": 4, "time": 30, "tags": ["legumes", "lowcarb", "reequilibrage"], "light": true, "ing": [{"n": "brocoli", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "cubes de bouillon", "q": 1, "u": "pièce", "r": "Épicerie"}, {"n": "fromage frais", "q": 100, "u": "g", "r": "Crémerie"}, {"n": "graines de courge", "q": 30, "u": "g", "r": "Épicerie"}], "steps": "Faire revenir l'oignon émincé.\nAjouter le brocoli en bouquets, couvrir d'eau avec le bouillon.\nCuire 20 min puis mixer avec le fromage frais.\nServir parsemé de graines de courge grillées."}, "chili-sin-carne": {"name": "Chili sin carne", "cat": "Végé", "serves": 4, "time": 40, "tags": ["legumes", "reequilibrage"], "light": true, "ing": [{"n": "haricots rouges", "q": 2, "u": "boîte", "r": "Épicerie"}, {"n": "maïs (conserve)", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "tomates concassées", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "poivrons", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "carottes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "cumin", "q": 1, "u": "c. à s.", "r": "Épicerie"}, {"n": "riz complet", "q": 250, "u": "g", "r": "Épicerie"}], "steps": "Faire revenir oignon, poivrons et carottes en dés.\nAjouter cumin, tomates, haricots et maïs égouttés.\nMijoter 25 min.\nServir avec le riz complet."}, "poivrons-farcis-quinoa": {"name": "Poivrons farcis au quinoa", "cat": "Végé", "serves": 4, "time": 50, "tags": ["legumes", "reequilibrage"], "light": true, "ing": [{"n": "poivrons", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "quinoa", "q": 150, "u": "g", "r": "Épicerie"}, {"n": "courgettes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates cerises", "q": 200, "u": "g", "r": "Fruits & légumes"}, {"n": "feta", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "basilic", "q": 1, "u": "botte", "r": "Fruits & légumes"}], "steps": "Cuire le quinoa 12 min.\nFaire revenir oignon et courgette en dés, ajouter les tomates coupées.\nMélanger avec le quinoa, la feta et le basilic, garnir les poivrons évidés.\nCuire 30 min à 180 °C."}, "bowl-patate-douce": {"name": "Bowl patate douce et pois chiches", "cat": "Végé", "serves": 4, "time": 35, "tags": ["legumes", "reequilibrage"], "light": true, "ing": [{"n": "patates douces", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "pois chiches", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "jeunes pousses d'épinards", "q": 150, "u": "g", "r": "Fruits & légumes"}, {"n": "avocats", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "concombre", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "yaourt grec", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "paprika", "q": 1, "u": "c. à c.", "r": "Épicerie"}], "steps": "Couper les patates douces en cubes, rôtir 25 min à 200 °C avec les pois chiches et le paprika.\nPréparer une sauce yaourt, citron, sel.\nGarnir les bols de pousses d'épinards, concombre et avocat.\nAjouter patates douces et pois chiches, napper de sauce."}, "poelee-legumes-quinoa": {"name": "Poêlée de légumes d'automne au quinoa", "cat": "Végé", "serves": 4, "time": 35, "tags": ["legumes", "reequilibrage"], "light": true, "ing": [{"n": "quinoa", "q": 250, "u": "g", "r": "Épicerie"}, {"n": "butternut", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "champignons", "q": 250, "u": "g", "r": "Fruits & légumes"}, {"n": "poireaux", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "noisettes", "q": 40, "u": "g", "r": "Épicerie"}, {"n": "huile d'olive", "q": 2, "u": "c. à s.", "r": "Épicerie"}], "steps": "Cuire le quinoa.\nPoêler la butternut en dés 15 min dans l'huile.\nAjouter poireaux émincés et champignons, 10 min.\nMélanger avec le quinoa et les noisettes concassées."}, "gratin-chou-fleur": {"name": "Gratin de chou-fleur léger", "cat": "Végé", "serves": 4, "time": 45, "tags": ["legumes", "lowcarb"], "light": false, "ing": [{"n": "chou-fleur", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "lait demi-écrémé", "q": 40, "u": "cl", "r": "Crémerie"}, {"n": "maïzena", "q": 2, "u": "c. à s.", "r": "Épicerie"}, {"n": "gruyère râpé", "q": 60, "u": "g", "r": "Crémerie"}, {"n": "muscade", "q": 1, "u": "pincée", "r": "Épicerie"}, {"n": "jambon", "q": 4, "u": "tranche", "r": "Boucherie & poisson"}], "steps": "Cuire le chou-fleur en bouquets 10 min à la vapeur.\nÉpaissir le lait chaud avec la maïzena, ajouter muscade, sel et poivre.\nMettre le chou-fleur dans un plat, napper de sauce, parsemer de gruyère.\nGratiner 20 min à 200 °C, servir avec le jambon."}, "aubergines-farcies": {"name": "Aubergines farcies à la viande", "cat": "Plat", "serves": 4, "time": 55, "tags": ["legumes", "lowcarb"], "light": true, "ing": [{"n": "aubergines", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "bœuf haché 5 %", "q": 400, "u": "g", "r": "Boucherie & poisson"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates concassées", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "gousses d'ail", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "persil", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "parmesan", "q": 40, "u": "g", "r": "Crémerie"}], "steps": "Couper les aubergines en deux, quadriller la chair, cuire 20 min à 200 °C.\nFaire revenir oignon, ail et viande, ajouter les tomates, 10 min.\nPrélever la chair des aubergines, la mélanger à la farce avec le persil.\nGarnir, parsemer de parmesan, cuire 15 min à 200 °C."}, "poulet-haricots-riz-complet": {"name": "Poulet, haricots verts et riz complet", "cat": "Plat", "serves": 4, "time": 30, "tags": ["reequilibrage"], "light": true, "ing": [{"n": "blancs de poulet", "q": 500, "u": "g", "r": "Boucherie & poisson"}, {"n": "haricots verts", "q": 600, "u": "g", "r": "Surgelés"}, {"n": "riz complet", "q": 250, "u": "g", "r": "Épicerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "huile d'olive", "q": 1, "u": "c. à s.", "r": "Épicerie"}, {"n": "herbes de Provence", "q": 1, "u": "c. à c.", "r": "Épicerie"}], "steps": "Cuire le riz complet (environ 25 min).\nCuire les haricots verts 10 min à la vapeur.\nPoêler le poulet en tranches avec l'huile et les herbes.\nServir avec un filet de citron."}, "saumon-quinoa-epinards": {"name": "Saumon, quinoa et épinards", "cat": "Rapide", "serves": 4, "time": 25, "tags": ["reequilibrage"], "light": true, "ing": [{"n": "pavés de saumon", "q": 4, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "quinoa", "q": 250, "u": "g", "r": "Épicerie"}, {"n": "épinards", "q": 400, "u": "g", "r": "Fruits & légumes"}, {"n": "gousses d'ail", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "graines de sésame", "q": 1, "u": "c. à s.", "r": "Épicerie"}], "steps": "Cuire le quinoa 12 min.\nFaire tomber les épinards avec l'ail dans une poêle.\nCuire le saumon 4 min par face.\nServir avec citron et sésame."}, "colin-puree-patate-douce": {"name": "Colin et purée de patate douce", "cat": "Plat", "serves": 4, "time": 35, "tags": ["reequilibrage"], "light": true, "ing": [{"n": "filets de colin", "q": 4, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "patates douces", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "carottes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "lait demi-écrémé", "q": 10, "u": "cl", "r": "Crémerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "ciboulette", "q": 1, "u": "botte", "r": "Fruits & légumes"}], "steps": "Cuire patates douces et carottes en morceaux 20 min.\nLes écraser avec le lait chaud.\nCuire le colin 10 min à la vapeur ou en papillote.\nServir avec citron et ciboulette."}, "salade-lentilles-oeuf": {"name": "Salade de lentilles, œuf et crudités", "cat": "Rapide", "serves": 4, "time": 25, "tags": ["reequilibrage", "legumes"], "light": true, "ing": [{"n": "lentilles vertes (cuites)", "q": 2, "u": "boîte", "r": "Épicerie"}, {"n": "œufs", "q": 4, "u": "pièce", "r": "Crémerie"}, {"n": "carottes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "échalotes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "persil", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "moutarde", "q": 1, "u": "c. à c.", "r": "Épicerie"}, {"n": "vinaigre", "q": 2, "u": "c. à s.", "r": "Épicerie"}], "steps": "Cuire les œufs 9 min, les écaler.\nRâper les carottes, couper les tomates, émincer l'échalote.\nPréparer une vinaigrette moutarde, vinaigre, un peu d'huile.\nMélanger lentilles et légumes, ajouter les œufs et le persil."}, "bowl-poulet-boulgour": {"name": "Bowl poulet, boulgour et crudités", "cat": "Rapide", "serves": 4, "time": 25, "tags": ["reequilibrage"], "light": true, "ing": [{"n": "blancs de poulet", "q": 400, "u": "g", "r": "Boucherie & poisson"}, {"n": "boulgour", "q": 200, "u": "g", "r": "Épicerie"}, {"n": "concombre", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates cerises", "q": 250, "u": "g", "r": "Fruits & légumes"}, {"n": "carottes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "yaourt grec", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "menthe", "q": 1, "u": "botte", "r": "Fruits & légumes"}], "steps": "Cuire le boulgour 10 min.\nPoêler le poulet en lanières.\nCouper concombre et tomates, râper les carottes.\nComposer les bols, servir avec une sauce yaourt et menthe."}, "dinde-champignons-pates-completes": {"name": "Dinde aux champignons et pâtes complètes", "cat": "Plat", "serves": 4, "time": 30, "tags": ["reequilibrage"], "light": true, "ing": [{"n": "escalopes de dinde", "q": 4, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "champignons", "q": 300, "u": "g", "r": "Fruits & légumes"}, {"n": "pâtes complètes", "q": 250, "u": "g", "r": "Épicerie"}, {"n": "crème légère", "q": 15, "u": "cl", "r": "Crémerie"}, {"n": "échalotes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "haricots verts", "q": 400, "u": "g", "r": "Surgelés"}], "steps": "Cuire les pâtes et les haricots verts.\nDorer la dinde en lanières, réserver.\nFaire revenir échalote et champignons, ajouter la crème.\nRemettre la dinde, servir avec pâtes et haricots."}, "curry-legumes-lentilles": {"name": "Curry de légumes et lentilles", "cat": "Végé", "serves": 4, "time": 35, "tags": ["reequilibrage", "legumes"], "light": true, "ing": [{"n": "lentilles corail", "q": 200, "u": "g", "r": "Épicerie"}, {"n": "chou-fleur", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "carottes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "épinards", "q": 150, "u": "g", "r": "Fruits & légumes"}, {"n": "lait de coco léger", "q": 20, "u": "cl", "r": "Épicerie"}, {"n": "tomates concassées", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "curry en poudre", "q": 2, "u": "c. à c.", "r": "Épicerie"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Faire revenir l'oignon avec le curry.\nAjouter chou-fleur en bouquets, carottes, lentilles, tomates et 40 cl d'eau.\nCuire 20 min, ajouter le lait de coco et les épinards.\nServir tel quel ou avec un peu de riz basmati."}, "spaghettis-courgettes-bolognaise": {"name": "Spaghettis de courgettes bolognaise", "cat": "Plat", "serves": 4, "time": 30, "tags": ["lowcarb", "legumes"], "light": true, "ing": [{"n": "courgettes", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "bœuf haché 5 %", "q": 400, "u": "g", "r": "Boucherie & poisson"}, {"n": "coulis de tomate", "q": 50, "u": "cl", "r": "Épicerie"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "carottes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "gousses d'ail", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "parmesan", "q": 40, "u": "g", "r": "Crémerie"}], "steps": "Préparer la bolognaise : oignon, carotte, ail, viande, puis coulis, 20 min.\nTailler les courgettes en spaghettis (spiraliseur ou économe).\nLes poêler 3 min seulement.\nServir avec la sauce et le parmesan."}, "riz-chou-fleur-crevettes": {"name": "Riz de chou-fleur sauté aux crevettes", "cat": "Rapide", "serves": 4, "time": 25, "tags": ["lowcarb", "legumes"], "light": true, "ing": [{"n": "chou-fleur", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "crevettes décortiquées", "q": 400, "u": "g", "r": "Surgelés"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "petits pois", "q": 150, "u": "g", "r": "Surgelés"}, {"n": "oignons nouveaux", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "sauce soja", "q": 3, "u": "c. à s.", "r": "Épicerie"}, {"n": "gingembre", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Mixer le chou-fleur en grains de la taille du riz.\nSauter crevettes et gingembre au wok, réserver.\nSauter le chou-fleur et les petits pois 6 min, pousser sur le côté et brouiller les œufs.\nRemettre les crevettes, ajouter soja et oignons nouveaux."}, "omelette-epinards-feta": {"name": "Omelette épinards et feta", "cat": "Rapide", "serves": 4, "time": 15, "tags": ["lowcarb"], "light": true, "ing": [{"n": "œufs", "q": 8, "u": "pièce", "r": "Crémerie"}, {"n": "épinards", "q": 200, "u": "g", "r": "Fruits & légumes"}, {"n": "feta", "q": 100, "u": "g", "r": "Crémerie"}, {"n": "tomates cerises", "q": 200, "u": "g", "r": "Fruits & légumes"}, {"n": "salade verte", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Faire tomber les épinards dans une poêle.\nVerser les œufs battus, parsemer de feta émiettée.\nCuire à feu doux, couvert.\nServir avec les tomates cerises et la salade."}, "saumon-haricots-citron": {"name": "Saumon, haricots verts et sauce citron", "cat": "Rapide", "serves": 4, "time": 20, "tags": ["lowcarb", "reequilibrage"], "light": true, "ing": [{"n": "pavés de saumon", "q": 4, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "haricots verts", "q": 600, "u": "g", "r": "Surgelés"}, {"n": "yaourt grec", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "aneth", "q": 1, "u": "botte", "r": "Fruits & légumes"}], "steps": "Cuire les haricots verts 10 min à la vapeur.\nCuire le saumon au four 12 min à 200 °C.\nMélanger yaourt, jus et zeste de citron, aneth.\nServir le saumon et les haricots avec la sauce."}, "poulet-legumes-soleil": {"name": "Poulet aux légumes du soleil", "cat": "Plat", "serves": 4, "time": 50, "tags": ["lowcarb", "legumes"], "light": true, "ing": [{"n": "cuisses de poulet", "q": 4, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "courgettes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "poivrons", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons rouges", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates cerises", "q": 250, "u": "g", "r": "Fruits & légumes"}, {"n": "olives noires", "q": 50, "u": "g", "r": "Épicerie"}, {"n": "herbes de Provence", "q": 1, "u": "c. à s.", "r": "Épicerie"}, {"n": "huile d'olive", "q": 2, "u": "c. à s.", "r": "Épicerie"}], "steps": "Couper les légumes en gros morceaux, les étaler dans un plat avec l'huile et les herbes.\nPoser les cuisses de poulet dessus.\nRôtir 45 min à 200 °C.\nAjouter les olives 5 min avant la fin."}, "salade-nicoise": {"name": "Salade niçoise sans féculents", "cat": "Rapide", "serves": 4, "time": 20, "tags": ["lowcarb"], "light": true, "ing": [{"n": "thon au naturel", "q": 2, "u": "boîte", "r": "Épicerie"}, {"n": "œufs", "q": 4, "u": "pièce", "r": "Crémerie"}, {"n": "haricots verts", "q": 300, "u": "g", "r": "Surgelés"}, {"n": "tomates", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "poivrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "olives noires", "q": 60, "u": "g", "r": "Épicerie"}, {"n": "salade verte", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "anchois", "q": 1, "u": "boîte", "r": "Épicerie"}], "steps": "Cuire œufs (9 min) et haricots verts (10 min), refroidir.\nCouper tomates et poivron.\nDisposer salade, légumes, thon, œufs et olives.\nAjouter les anchois et une vinaigrette légère."}, "quiche-sans-pate-poireaux-saumon": {"name": "Quiche sans pâte poireaux et saumon", "cat": "Plat", "serves": 4, "time": 45, "tags": ["lowcarb"], "light": true, "ing": [{"n": "poireaux", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "saumon fumé", "q": 150, "u": "g", "r": "Boucherie & poisson"}, {"n": "œufs", "q": 4, "u": "pièce", "r": "Crémerie"}, {"n": "lait demi-écrémé", "q": 25, "u": "cl", "r": "Crémerie"}, {"n": "fromage frais", "q": 100, "u": "g", "r": "Crémerie"}, {"n": "salade verte", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Émincer les poireaux et les faire fondre 15 min.\nBattre œufs, lait et fromage frais.\nMettre poireaux et saumon en morceaux dans un plat, verser l'appareil.\nCuire 30 min à 180 °C, servir avec la salade."}, "brochettes-dinde-taboule-chou-fleur": {"name": "Brochettes de dinde et taboulé de chou-fleur", "cat": "Plat", "serves": 4, "time": 35, "tags": ["lowcarb", "reequilibrage"], "light": true, "ing": [{"n": "escalopes de dinde", "q": 500, "u": "g", "r": "Boucherie & poisson"}, {"n": "chou-fleur", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "concombre", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "tomates", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "menthe", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "persil", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "citrons", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "paprika", "q": 1, "u": "c. à c.", "r": "Épicerie"}], "steps": "Couper la dinde en cubes, mariner avec paprika et jus d'un citron, embrocher.\nMixer le chou-fleur cru en semoule.\nMélanger avec concombre, tomates, herbes et jus du second citron.\nGriller les brochettes 10 min, servir avec le taboulé."}},"desserts1":{"carrot-cake": {"name": "Carrot cake", "cat": "Dessert", "serves": 6, "time": 60, "tags": ["legumes", "dessert-legumes"], "ing": [{"n": "carottes", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "farine", "q": 200, "u": "g", "r": "Épicerie"}, {"n": "sucre roux", "q": 120, "u": "g", "r": "Épicerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "huile", "q": 10, "u": "cl", "r": "Épicerie"}, {"n": "noix", "q": 60, "u": "g", "r": "Épicerie"}, {"n": "cannelle", "q": 2, "u": "c. à c.", "r": "Épicerie"}, {"n": "levure chimique", "q": 1, "u": "sachet", "r": "Épicerie"}, {"n": "fromage frais", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "sucre glace", "q": 40, "u": "g", "r": "Épicerie"}], "steps": "Râper finement les carottes.\nFouetter œufs, sucre et huile, ajouter farine, levure et cannelle.\nIncorporer carottes et noix concassées, verser dans un moule.\nCuire 40 min à 180 °C. Laisser refroidir, napper de fromage frais mélangé au sucre glace."}, "fondant-chocolat-courgette": {"name": "Fondant chocolat-courgette", "cat": "Dessert", "serves": 6, "time": 45, "tags": ["legumes", "dessert-legumes", "reequilibrage"], "ing": [{"n": "courgettes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "chocolat noir", "q": 150, "u": "g", "r": "Épicerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "sucre", "q": 60, "u": "g", "r": "Épicerie"}, {"n": "poudre d'amande", "q": 50, "u": "g", "r": "Épicerie"}, {"n": "farine", "q": 30, "u": "g", "r": "Épicerie"}], "steps": "Râper la courgette sans la peler, bien l'essorer.\nFaire fondre le chocolat.\nFouetter œufs et sucre, ajouter chocolat, poudre d'amande, farine et courgette.\nCuire 25 min à 180 °C : le cœur reste fondant."}, "tarte-potiron": {"name": "Tarte au potiron à la cannelle", "cat": "Dessert", "serves": 6, "time": 65, "tags": ["legumes", "dessert-legumes"], "ing": [{"n": "potiron", "q": 600, "u": "g", "r": "Fruits & légumes"}, {"n": "pâte sablée", "q": 1, "u": "pièce", "r": "Crémerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "sucre roux", "q": 80, "u": "g", "r": "Épicerie"}, {"n": "lait", "q": 15, "u": "cl", "r": "Crémerie"}, {"n": "cannelle", "q": 1, "u": "c. à c.", "r": "Épicerie"}, {"n": "gingembre en poudre", "q": 1, "u": "pincée", "r": "Épicerie"}], "steps": "Cuire le potiron en dés 15 min à la vapeur, l'écraser en purée.\nMélanger avec œufs, sucre, lait et épices.\nVerser sur la pâte étalée dans le moule.\nCuire 40 min à 180 °C. Servir tiède ou froid."}, "brownie-haricots-rouges": {"name": "Brownie aux haricots rouges", "cat": "Dessert", "serves": 6, "time": 40, "tags": ["legumes", "dessert-legumes", "reequilibrage"], "ing": [{"n": "haricots rouges", "q": 1, "u": "boîte", "r": "Épicerie"}, {"n": "chocolat noir", "q": 120, "u": "g", "r": "Épicerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "sucre", "q": 70, "u": "g", "r": "Épicerie"}, {"n": "cacao en poudre", "q": 2, "u": "c. à s.", "r": "Épicerie"}, {"n": "noix de pécan", "q": 50, "u": "g", "r": "Épicerie"}], "steps": "Rincer et égoutter les haricots, les mixer en purée très lisse.\nFaire fondre le chocolat, l'ajouter avec œufs, sucre et cacao, mixer encore.\nVerser dans un moule, parsemer de noix de pécan.\nCuire 25 min à 180 °C, laisser refroidir avant de couper."}, "muffins-courgette-citron": {"name": "Muffins courgette et citron", "cat": "Dessert", "serves": 12, "time": 35, "tags": ["legumes", "dessert-legumes"], "ing": [{"n": "courgettes", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "farine", "q": 200, "u": "g", "r": "Épicerie"}, {"n": "sucre", "q": 100, "u": "g", "r": "Épicerie"}, {"n": "œufs", "q": 2, "u": "pièce", "r": "Crémerie"}, {"n": "yaourts nature", "q": 1, "u": "pièce", "r": "Crémerie"}, {"n": "huile", "q": 6, "u": "cl", "r": "Épicerie"}, {"n": "levure chimique", "q": 1, "u": "sachet", "r": "Épicerie"}], "steps": "Râper la courgette et l'essorer, râper le zeste du citron.\nMélanger œufs, sucre, yaourt, huile et jus de citron.\nAjouter farine, levure, zeste et courgette.\nRemplir 12 moules à muffins, cuire 20 min à 180 °C."}, "gateau-betterave-chocolat": {"name": "Gâteau betterave et chocolat", "cat": "Dessert", "serves": 6, "time": 55, "tags": ["legumes", "dessert-legumes"], "ing": [{"n": "betteraves cuites", "q": 250, "u": "g", "r": "Fruits & légumes"}, {"n": "chocolat noir", "q": 150, "u": "g", "r": "Épicerie"}, {"n": "beurre", "q": 80, "u": "g", "r": "Crémerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "sucre", "q": 100, "u": "g", "r": "Épicerie"}, {"n": "farine", "q": 80, "u": "g", "r": "Épicerie"}, {"n": "levure chimique", "q": 1, "u": "c. à c.", "r": "Épicerie"}], "steps": "Mixer les betteraves en purée.\nFaire fondre chocolat et beurre.\nFouetter œufs et sucre, ajouter le chocolat, la betterave, la farine et la levure.\nCuire 35 min à 180 °C."}, "flan-butternut": {"name": "Flan de butternut à la vanille", "cat": "Dessert", "serves": 6, "time": 50, "tags": ["legumes", "dessert-legumes", "lowcarb"], "ing": [{"n": "butternut", "q": 500, "u": "g", "r": "Fruits & légumes"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "lait", "q": 30, "u": "cl", "r": "Crémerie"}, {"n": "sucre roux", "q": 50, "u": "g", "r": "Épicerie"}, {"n": "sucre vanillé", "q": 1, "u": "sachet", "r": "Épicerie"}, {"n": "cannelle", "q": 1, "u": "pincée", "r": "Épicerie"}], "steps": "Cuire la butternut en dés 15 min à la vapeur.\nMixer avec le lait, les œufs, les sucres et la cannelle.\nVerser dans des ramequins.\nCuire 30 min à 160 °C au bain-marie, servir frais."}, "cake-patate-douce": {"name": "Cake moelleux à la patate douce", "cat": "Dessert", "serves": 6, "time": 55, "tags": ["legumes", "dessert-legumes"], "ing": [{"n": "patates douces", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "farine", "q": 180, "u": "g", "r": "Épicerie"}, {"n": "sucre roux", "q": 90, "u": "g", "r": "Épicerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "beurre", "q": 60, "u": "g", "r": "Crémerie"}, {"n": "levure chimique", "q": 1, "u": "sachet", "r": "Épicerie"}, {"n": "cannelle", "q": 1, "u": "c. à c.", "r": "Épicerie"}, {"n": "noix de coco râpée", "q": 30, "u": "g", "r": "Épicerie"}], "steps": "Cuire la patate douce en dés 15 min, l'écraser.\nMélanger avec œufs, sucre et beurre fondu.\nAjouter farine, levure, cannelle et noix de coco.\nCuire 40 min à 180 °C dans un moule à cake."}},"fetes1":{"fete-saint-jacques": {"name": "Noix de Saint-Jacques poêlées, fondue de poireaux", "cat": "Entrée", "serves": 6, "time": 30, "tags": ["fete", "lowcarb"], "ing": [{"n": "noix de Saint-Jacques", "q": 18, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "poireaux", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "crème fraîche", "q": 15, "u": "cl", "r": "Crémerie"}, {"n": "beurre", "q": 40, "u": "g", "r": "Crémerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Émincer les poireaux et les faire fondre 15 min au beurre, ajouter la crème.\nSécher les noix de Saint-Jacques.\nLes saisir 1 min 30 par face dans une poêle très chaude avec un peu de beurre.\nServir sur la fondue de poireaux, un filet de citron."}, "fete-veloute-chataignes": {"name": "Velouté de châtaignes", "cat": "Entrée", "serves": 6, "time": 40, "tags": ["fete"], "ing": [{"n": "châtaignes cuites", "q": 400, "u": "g", "r": "Épicerie"}, {"n": "oignons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "cubes de bouillon", "q": 1, "u": "pièce", "r": "Épicerie"}, {"n": "crème fraîche", "q": 15, "u": "cl", "r": "Crémerie"}, {"n": "lardons", "q": 100, "u": "g", "r": "Boucherie & poisson"}], "steps": "Faire revenir l'oignon.\nAjouter les châtaignes et 1 l de bouillon, cuire 20 min.\nMixer avec la crème.\nServir avec des lardons grillés."}, "fete-verrines-avocat-crevettes": {"name": "Verrines avocat, crevettes et pamplemousse", "cat": "Entrée", "serves": 6, "time": 20, "tags": ["fete", "lowcarb"], "ing": [{"n": "avocats", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "crevettes décortiquées", "q": 250, "u": "g", "r": "Surgelés"}, {"n": "pamplemousse", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "citrons verts", "q": 1, "u": "pièce", "r": "Fruits & légumes"}, {"n": "fromage frais", "q": 100, "u": "g", "r": "Crémerie"}, {"n": "ciboulette", "q": 1, "u": "botte", "r": "Fruits & légumes"}], "steps": "Écraser les avocats avec le jus de citron vert.\nCouper le pamplemousse en suprêmes.\nFouetter le fromage frais avec la ciboulette.\nMonter les verrines : avocat, fromage, crevettes, pamplemousse. Servir frais."}, "fete-gravlax": {"name": "Saumon gravlax à l'aneth", "cat": "Entrée", "serves": 6, "time": 20, "tags": ["fete"], "ing": [{"n": "filet de saumon", "q": 600, "u": "g", "r": "Boucherie & poisson"}, {"n": "gros sel", "q": 100, "u": "g", "r": "Épicerie"}, {"n": "sucre", "q": 80, "u": "g", "r": "Épicerie"}, {"n": "aneth", "q": 2, "u": "botte", "r": "Fruits & légumes"}, {"n": "baies roses", "q": 1, "u": "c. à s.", "r": "Épicerie"}, {"n": "blinis", "q": 12, "u": "pièce", "r": "Boulangerie"}], "steps": "Mélanger sel, sucre, aneth haché et baies roses.\nEn recouvrir le saumon, filmer, laisser 24 h au frais en le retournant à mi-temps.\nRincer, sécher, trancher finement.\nServir avec des blinis et un peu de crème à l'aneth."}, "fete-foie-gras-mi-cuit": {"name": "Foie gras mi-cuit au torchon simplifié", "cat": "Entrée", "serves": 6, "time": 40, "tags": ["fete"], "ing": [{"n": "lobe de foie gras cru", "q": 500, "u": "g", "r": "Boucherie & poisson"}, {"n": "sel", "q": 8, "u": "g", "r": "Épicerie"}, {"n": "poivre", "q": 1, "u": "pincée", "r": "Épicerie"}, {"n": "porto", "q": 3, "u": "cl", "r": "Épicerie"}, {"n": "pain de campagne", "q": 1, "u": "pièce", "r": "Boulangerie"}], "steps": "Dénerver le foie gras à température ambiante.\nAssaisonner sel, poivre, arroser de porto, laisser 2 h au frais.\nRouler serré dans du film, pocher 20 min à 70 °C dans l'eau.\nRefroidir 24 h au frais. Servir tranché sur du pain grillé."}, "fete-chapon-marrons": {"name": "Chapon rôti aux marrons", "cat": "Plat", "serves": 8, "time": 180, "tags": ["fete"], "ing": [{"n": "chapon", "q": 1, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "marrons cuits", "q": 400, "u": "g", "r": "Épicerie"}, {"n": "échalotes", "q": 4, "u": "pièce", "r": "Fruits & légumes"}, {"n": "beurre", "q": 60, "u": "g", "r": "Crémerie"}, {"n": "cubes de bouillon", "q": 1, "u": "pièce", "r": "Épicerie"}, {"n": "pommes de terre", "q": 1, "u": "kg", "r": "Fruits & légumes"}], "steps": "Badigeonner le chapon de beurre, saler, poivrer.\nRôtir 2 h 30 à 180 °C en arrosant souvent, avec un verre de bouillon.\n30 min avant la fin, ajouter marrons, échalotes et pommes de terre autour.\nLaisser reposer 10 min avant de découper."}, "fete-boeuf-wellington": {"name": "Filet de bœuf en croûte (Wellington)", "cat": "Plat", "serves": 6, "time": 90, "tags": ["fete"], "ing": [{"n": "filet de bœuf", "q": 1, "u": "kg", "r": "Boucherie & poisson"}, {"n": "pâte feuilletée", "q": 2, "u": "pièce", "r": "Crémerie"}, {"n": "champignons", "q": 500, "u": "g", "r": "Fruits & légumes"}, {"n": "jambon cru", "q": 6, "u": "tranche", "r": "Boucherie & poisson"}, {"n": "échalotes", "q": 2, "u": "pièce", "r": "Fruits & légumes"}, {"n": "œufs", "q": 1, "u": "pièce", "r": "Crémerie"}, {"n": "moutarde", "q": 2, "u": "c. à s.", "r": "Épicerie"}], "steps": "Saisir le filet de tous côtés, le badigeonner de moutarde.\nHacher champignons et échalotes, cuire jusqu'à évaporation complète.\nEnvelopper le filet de jambon cru et de champignons, puis de pâte feuilletée.\nDorer à l'œuf, cuire 35 min à 200 °C. Reposer 10 min avant de trancher."}, "fete-magret-figues": {"name": "Magrets de canard aux figues", "cat": "Plat", "serves": 6, "time": 35, "tags": ["fete", "lowcarb"], "ing": [{"n": "magrets de canard", "q": 3, "u": "pièce", "r": "Boucherie & poisson"}, {"n": "figues", "q": 9, "u": "pièce", "r": "Fruits & légumes"}, {"n": "miel", "q": 2, "u": "c. à s.", "r": "Épicerie"}, {"n": "porto", "q": 10, "u": "cl", "r": "Épicerie"}, {"n": "haricots verts", "q": 600, "u": "g", "r": "Surgelés"}], "steps": "Quadriller la peau des magrets, les cuire 8 min côté peau puis 4 min côté chair.\nLes laisser reposer sous aluminium.\nDans la poêle, faire caraméliser les figues coupées avec le miel, déglacer au porto.\nTrancher les magrets, servir avec les figues et les haricots verts."}, "fete-gigot-7-heures": {"name": "Gigot d'agneau de 7 heures", "cat": "Plat", "serves": 8, "time": 450, "tags": ["fete"], "ing": [{"n": "gigot d'agneau", "q": 2.2, "u": "kg", "r": "Boucherie & poisson"}, {"n": "gousses d'ail", "q": 10, "u": "pièce", "r": "Fruits & légumes"}, {"n": "carottes", "q": 6, "u": "pièce", "r": "Fruits & légumes"}, {"n": "oignons", "q": 3, "u": "pièce", "r": "Fruits & légumes"}, {"n": "vin blanc", "q": 50, "u": "cl", "r": "Épicerie"}, {"n": "thym", "q": 1, "u": "botte", "r": "Fruits & légumes"}, {"n": "cubes de bouillon", "q": 1, "u": "pièce", "r": "Épicerie"}], "steps": "Dorer le gigot dans une cocotte en fonte.\nAjouter légumes, ail en chemise, thym, vin et bouillon.\nFermer et cuire 7 h à 120 °C.\nLa viande se découpe à la cuillère. Servir avec son jus et les légumes."}, "fete-saumon-croute": {"name": "Saumon en croûte aux épinards", "cat": "Plat", "serves": 6, "time": 60, "tags": ["fete"], "ing": [{"n": "filet de saumon", "q": 1, "u": "kg", "r": "Boucherie & poisson"}, {"n": "pâte feuilletée", "q": 2, "u": "pièce", "r": "Crémerie"}, {"n": "épinards", "q": 400, "u": "g", "r": "Fruits & légumes"}, {"n": "fromage frais", "q": 150, "u": "g", "r": "Crémerie"}, {"n": "œufs", "q": 1, "u": "pièce", "r": "Crémerie"}, {"n": "citrons", "q": 1, "u": "pièce", "r": "Fruits & légumes"}], "steps": "Faire tomber les épinards, bien les essorer, les mélanger au fromage frais.\nPoser le saumon sur une pâte, le recouvrir des épinards.\nCouvrir de la seconde pâte, souder les bords, dorer à l'œuf.\nCuire 35 min à 200 °C. Servir avec du citron."}, "fete-buche-chocolat": {"name": "Bûche de Noël au chocolat", "cat": "Dessert", "serves": 8, "time": 60, "tags": ["fete"], "ing": [{"n": "œufs", "q": 4, "u": "pièce", "r": "Crémerie"}, {"n": "sucre", "q": 120, "u": "g", "r": "Épicerie"}, {"n": "farine", "q": 80, "u": "g", "r": "Épicerie"}, {"n": "cacao en poudre", "q": 20, "u": "g", "r": "Épicerie"}, {"n": "chocolat noir", "q": 200, "u": "g", "r": "Épicerie"}, {"n": "crème liquide entière", "q": 40, "u": "cl", "r": "Crémerie"}, {"n": "sucre glace", "q": 20, "u": "g", "r": "Épicerie"}], "steps": "Biscuit : fouetter œufs et sucre, ajouter farine et cacao, étaler sur une plaque, cuire 8 min à 200 °C.\nRouler le biscuit chaud dans un torchon.\nGanache : verser la crème chaude sur le chocolat, laisser refroidir puis fouetter.\nDérouler, garnir de ganache, rouler, couvrir du reste. Strier à la fourchette, saupoudrer de sucre glace."}, "fete-buche-marrons": {"name": "Bûche aux marrons sans cuisson", "cat": "Dessert", "serves": 8, "time": 30, "tags": ["fete"], "ing": [{"n": "crème de marrons", "q": 500, "u": "g", "r": "Épicerie"}, {"n": "beurre", "q": 125, "u": "g", "r": "Crémerie"}, {"n": "chocolat noir", "q": 100, "u": "g", "r": "Épicerie"}, {"n": "biscuits boudoirs", "q": 12, "u": "pièce", "r": "Épicerie"}, {"n": "marrons glacés", "q": 6, "u": "pièce", "r": "Épicerie"}], "steps": "Faire fondre le chocolat, le mélanger avec le beurre mou et la crème de marrons.\nTapisser un moule à cake de film, alterner crème et boudoirs.\nLaisser prendre 6 h au frais.\nDémouler, décorer de marrons glacés."}, "fete-galette-rois": {"name": "Galette des rois à la frangipane", "cat": "Dessert", "serves": 8, "time": 50, "tags": ["fete"], "ing": [{"n": "pâte feuilletée", "q": 2, "u": "pièce", "r": "Crémerie"}, {"n": "poudre d'amande", "q": 125, "u": "g", "r": "Épicerie"}, {"n": "sucre", "q": 100, "u": "g", "r": "Épicerie"}, {"n": "beurre", "q": 100, "u": "g", "r": "Crémerie"}, {"n": "œufs", "q": 3, "u": "pièce", "r": "Crémerie"}, {"n": "rhum", "q": 1, "u": "c. à s.", "r": "Épicerie"}], "steps": "Mélanger beurre mou, sucre, poudre d'amande, 2 œufs et le rhum.\nÉtaler la frangipane sur une pâte, sans oublier la fève.\nCouvrir de la seconde pâte, souder, dorer à l'œuf, dessiner au couteau.\nCuire 30 min à 180 °C."}, "fete-vacherin": {"name": "Vacherin glacé aux fruits rouges", "cat": "Dessert", "serves": 8, "time": 30, "tags": ["fete"], "ing": [{"n": "meringues", "q": 8, "u": "pièce", "r": "Épicerie"}, {"n": "glace vanille", "q": 500, "u": "ml", "r": "Surgelés"}, {"n": "sorbet framboise", "q": 500, "u": "ml", "r": "Surgelés"}, {"n": "fruits rouges", "q": 300, "u": "g", "r": "Surgelés"}, {"n": "crème liquide entière", "q": 25, "u": "cl", "r": "Crémerie"}, {"n": "sucre glace", "q": 30, "u": "g", "r": "Épicerie"}], "steps": "Tapisser un moule de film, alterner meringues émiettées, glace vanille et sorbet.\nRemettre au congélateur 4 h.\nFouetter la crème en chantilly avec le sucre glace.\nDémouler, couvrir de chantilly et de fruits rouges juste avant de servir."}}};
function applyPacks(){
  if(mode==="loading"||!menu||!recipes)return;
  const done=menu.packs||[]; let added=0;
  for(const[pid,list]of Object.entries(PACKS)){
    if(done.includes(pid))continue;
    for(const[id,r]of Object.entries(list))if(!recipes[id]&&!Object.values(recipes).some(x=>norm(x.name)===norm(r.name))){recipes[id]=Object.assign(JSON.parse(JSON.stringify(r)),{createdAt:new Date().toISOString()});added++;}
    menu.packs=[...(menu.packs||[]),pid];
  }
  if(menu.packs&&menu.packs.length!==done.length){LS.set("cm_recipes",recipes);LS.set("cm_menu",menu);scheduleSync();
    if(added)setTimeout(()=>toast(added+" nouvelles recettes ajoutées au carnet"),400);}
}
recipes=LS.get("cm_recipes",null)||JSON.parse(JSON.stringify(SEED)); // a copy: the built-in list itself must never change
menu=normMenu(LS.get("cm_menu",{}));
render();
setStatus(sync?"pending":"off");
if(sync)runSync();
startImportPolling();
renderNow(); setInterval(renderNow,20000);
setTimeout(resumeIfNeeded,120); // back from a website after the phone closed the app: reopen the same place
// the link stays in the address: an app added to the home screen from it keeps following the book (on iPhone its storage is separate from Safari)
(()=>{const m=location.search.match(/[?&]carnet=([^&]+)/);if(m){const u=followUrl(decodeURIComponent(m[1]));if(u&&!follows.some(f=>f.url===u))addFollow(u);}
  refreshFollows();pollSubs();pollPropAcks();document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"){refreshFollows();pollSubs();pollPropAcks();}});})();
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&sync)runSync();});
setInterval(()=>{if(sync&&document.visibilityState==="visible"&&!syncBusy)runSync();},30000);
/* keep open windows inside the visible area (keyboard on iPhone) */
(()=>{const vv=window.visualViewport;if(!vv)return;const d=document.documentElement;
  let tall=vv.height;const typing=()=>{const a=document.activeElement;return!!a&&(a.tagName==="TEXTAREA"||(a.tagName==="INPUT"&&!/^(checkbox|radio|button|submit|file|range)$/.test(a.type)));};
  const fit=()=>{d.style.setProperty("--vvh",vv.height+"px");d.style.setProperty("--vvt",vv.offsetTop+"px");
    tall=Math.max(tall,vv.height);
    const kb=typing()||Date.now()-blurAt<400||tall-vv.height>150||window.innerHeight-vv.height>150;d.classList.toggle("kb",kb); // keyboard open: tab bar hidden, window uses all the room
    const t=document.querySelector(".tabs");if(t&&!kb)d.style.setProperty("--tabh",t.offsetHeight+"px");};
  vv.addEventListener("resize",fit);vv.addEventListener("scroll",fit);window.addEventListener("orientationchange",()=>{tall=0;setTimeout(fit,400);});
  let blurAt=0;document.addEventListener("focusout",e=>{const t=e.target;if(t&&(t.tagName==="TEXTAREA"||(t.tagName==="INPUT"&&!/^(checkbox|radio|button|submit|file|range)$/.test(t.type))))blurAt=Date.now();}); // only leaving a text field
  document.addEventListener("focusin",fit);document.addEventListener("focusout",()=>setTimeout(fit,450)); // late enough for the tap on "Ajouter" or "Enregistrer" to land before the layout moves
  new MutationObserver(fit).observe(document.body,{subtree:true,attributes:true,attributeFilter:["hidden"]});fit();})();
/* inside a window, a drag only scrolls the window's own content: no bounce of the whole window */
(()=>{let y0=0,x0=0;
  document.addEventListener("touchstart",e=>{const t=e.touches[0];y0=t.clientY;x0=t.clientX;},{passive:true});
  document.addEventListener("touchmove",e=>{
    const sheet=e.target.closest&&e.target.closest(".sheet");if(!sheet||sheet.hidden)return;
    const t=e.touches[0],dy=t.clientY-y0,dx=t.clientX-x0;
    if(Math.abs(dx)<6&&Math.abs(dy)<6)return;
    if(Math.abs(dx)>Math.abs(dy)){let el=e.target;while(el&&el!==sheet){const cs=getComputedStyle(el);if(/(auto|scroll)/.test(cs.overflowX)&&el.scrollWidth>el.clientWidth)return;el=el.parentElement;}e.preventDefault();return;}
    const sc=e.target.closest(".sheet-in");
    if(!sc||sc.scrollHeight<=sc.clientHeight+1){e.preventDefault();return;}
    if((dy>0&&sc.scrollTop<=0)||(dy<0&&sc.scrollTop+sc.clientHeight>=sc.scrollHeight-1))e.preventDefault();
  },{passive:false});})();
/* leaving for a website (Google Images, a recipe site, a drive…): remember where we were, in case the phone restarts the app on return */
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[target="_blank"]');if(!a)return;
  const open=id=>!$("#"+id).hidden;
  LS.set("cm_resume",{at:Date.now(),view,y:window.scrollY,week:curWeek,rec:open("recSheet")||open("photoSheet")?recSheetId:null,photo:open("photoSheet")?photoId:null,review:open("reviewSheet"),slot:open("slotSheet")?slotK:null,openId});},true);
function resumeIfNeeded(){const r=LS.get("cm_resume",null);if(!r)return;LS.set("cm_resume",null);if(Date.now()-r.at>45*60e3)return;
  view=r.view||view;if(r.week)curWeek=r.week;if(r.openId)openId=r.openId;render();setTimeout(()=>window.scrollTo(0,r.y||0),50);
  if(r.review){reviewMode="all";reviewLimit=60;renderReview();$("#reviewSheet").hidden=false;}
  if(r.slot&&W()[r.slot]!==undefined){slotK=r.slot;renderSlotSheet();$("#slotSheet").hidden=false;}
  if(r.rec&&recipes[r.rec]){openRecSheet(r.rec);}
  if(r.photo&&recipes[r.photo])setTimeout(()=>openPhotoPick(r.photo),60);}
// the app is still alive when we come back: nothing to restore
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")LS.set("cm_resume",null);});
/* swipe left / right on a page to go to the next / previous tab */
(()=>{const ORDER=["menu","week","rec","shop","wine"];let x0=0,y0=0,t0=0,ok=false;
  document.addEventListener("touchstart",e=>{const t=e.touches[0];ok=e.touches.length===1;x0=t.clientX;y0=t.clientY;t0=Date.now();
    const el=e.target;if([...document.querySelectorAll(".sheet")].some(s=>!s.hidden)||el.closest(".sheet,.tabs,input,textarea,select,.undo-bar")){ok=false;return;}
    for(let n=el;n&&n!==document.body;n=n.parentElement){const cs=getComputedStyle(n);if(/(auto|scroll)/.test(cs.overflowX)&&n.scrollWidth>n.clientWidth+2){ok=false;return;}} // a row that scrolls sideways keeps the gesture
  },{passive:true});
  document.addEventListener("touchend",e=>{if(!ok)return;ok=false;const t=e.changedTouches[0],dx=t.clientX-x0,dy=t.clientY-y0;
    if(Date.now()-t0>700||Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.8)return;
    const i=ORDER.indexOf(view),j=i+(dx<0?1:-1);if(i<0||j<0||j>=ORDER.length)return;
    view=ORDER[j];LS.set("cm_view",view);render();window.scrollTo(0,0);
    const v=$("#v-"+view);if(v){v.classList.remove("swipe-l","swipe-r");void v.offsetWidth;v.classList.add(dx<0?"swipe-l":"swipe-r");}},{passive:true});})();
/* going back: when a window opened from another one is closed, the first one comes back */
let sheetBack=[], sheetPrev=new Set();
function clearSheetBack(){sheetBack=[];}
(()=>{const openSet=()=>new Set([...document.querySelectorAll(".sheet")].filter(s=>!s.hidden).map(s=>s.id));
  let t=null;
  const check=()=>{t=null;const now=openSet(),opened=[...now].filter(x=>!sheetPrev.has(x)),closed=[...sheetPrev].filter(x=>!now.has(x));
    if(opened.length&&closed.length)closed.forEach(c=>sheetBack.push({id:c,by:opened[0]}));
    else if(closed.length&&!now.size){const top=sheetBack[sheetBack.length-1];
      if(top&&closed.includes(top.by)){sheetBack.pop();const el=document.getElementById(top.id);
        if(el){if(top.id==="slotSheet"&&slotK)renderSlotSheet();if(top.id==="recSheet")renderRecSheet();el.hidden=false;sheetPrev=openSet();return;}}
      else sheetBack=[];}
    sheetPrev=now;};
  const mo=new MutationObserver(()=>{if(!t)t=setTimeout(check,0);});
  document.querySelectorAll(".sheet").forEach(s=>mo.observe(s,{attributes:true,attributeFilter:["hidden"]}));sheetPrev=openSet();})();
/* freeze the page behind any open sheet (iPhone keeps scrolling the background otherwise) */
(()=>{let y=0,frozen=false;
  const sync=()=>{const open=[...document.querySelectorAll(".sheet")].some(s=>!s.hidden);
    if(open&&!frozen){y=window.scrollY;document.body.style.top=(-y)+"px";document.body.classList.add("frozen");frozen=true;}
    else if(!open&&frozen){document.body.classList.remove("frozen");document.body.style.top="";window.scrollTo(0,y);frozen=false;}};
  const mo=new MutationObserver(sync);
  document.querySelectorAll(".sheet").forEach(s=>mo.observe(s,{attributes:true,attributeFilter:["hidden"]}));
  sync();})();
/* updates: check on every opening and reload as soon as a new version is published */
if("serviceWorker" in navigator){
  const hadSW=!!navigator.serviceWorker.controller; let reloading=false;
  navigator.serviceWorker.register("sw.js",{updateViaCache:"none"}).then(reg=>{
    const check=()=>{try{reg.update();}catch(e){}};
    document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")check();});
    setInterval(check,30*60*1000);
  }).catch(()=>{});
  navigator.serviceWorker.addEventListener("controllerchange",()=>{
    if(!hadSW||reloading)return;
    const busy=[...document.querySelectorAll(".sheet")].some(s=>!s.hidden);
    if(busy){toast("Nouvelle version de l'app : elle s'appliquera à la prochaine ouverture");return;}
    reloading=true;location.reload();
  });
}

/* ---------- ✏️ Noter un repas et 🥡 Restes (sans recette) : mêmes données que Maisonnée ---------- */
let slotFree=null;
const FREE_NOTES=["Pizza","Restaurant","Sandwichs","Chez des amis","Croque-monsieur","Plateau-repas","Pâtes vite faites","Omelette","Raclette","Fast-food"];
function freeRecent(k){
  const[dn,m]=k.split("|"),day=addDays(weekStartDate(),DAYS.indexOf(dn)),out=[],seen=new Set();
  for(let i=0;i<=3;i++){const d=addDays(day,-i),w=ymd(mondayOf(d)),dname=DAYS[(d.getDay()+6)%7];
    for(const mm of["soir","midi"]){if(i===0&&(m==="midi"||mm==="soir"))continue;const s=((menu.weeks||{})[w]||{})[slotKey(dname,mm)],r=s&&recipes[s.id];
      if(r&&!seen.has(r.name)){seen.add(r.name);out.push({name:r.name,when:i===0?"ce midi":i===1?"hier "+mm:dname.toLowerCase()+" "+mm});}}}
  return out;}
function renderSlotFree(){
  const k=slotK,note=slotFree==="note",bt=(t,lab)=>`<button type="button" class="btn" data-act="freePut" data-t="${esc(t)}">${esc(lab||t)}</button>`;
  let h=`<p class="muted" style="font-size:14px;margin:0 0 10px">${note?(isPast(k)?"Qu'avez-vous mangé ? ":"Notez simplement le repas. ")+"Aucune recette n'est créée, rien ne part aux courses.":"Un repas fait avec ce qui reste : rien ne part aux courses."}</p>`;
  if(note)h+=`<div class="chips" style="flex-wrap:wrap;overflow:visible">${FREE_NOTES.map(t=>`<button type="button" class="chip" data-act="freePut" data-t="${esc(t)}">${esc(t)}</button>`).join("")}</div>`;
  else{const rec=freeRecent(k);h+=rec.length?`<div class="slot-acts2" style="flex-direction:column;align-items:stretch">${rec.map(x=>bt(x.name,x.name+" · "+x.when)).join("")}</div>`:`<p class="muted" style="font-size:14px">Pas de plat noté ces 3 derniers jours.</p>`;}
  h+=`<div class="row" style="margin-top:12px;flex-wrap:nowrap"><input class="search" id="freeQ" maxlength="80" placeholder="${note?"ex. crêpes avec les enfants":"ex. lasagnes de dimanche"}" style="flex:1;margin:0;min-width:0"><button type="button" class="btn primary" data-act="freePut">OK</button></div>`;
  h+=`<div class="slot-acts2" style="margin-top:12px">${note?`<button type="button" class="btn" data-act="freeLeft">🥡 C'était des restes</button>`:bt("du frigo","🥡 Restes du frigo")}<button type="button" class="btn ghost" data-act="freeBack">← Retour</button></div>`;
  $("#slotTitle").textContent=(note?"✏️ ":"🥡 Restes · ")+slotLabel(k);
  $("#slotBody").innerHTML=h;
}
document.addEventListener("click",e=>{
  const b=e.target.closest("[data-act=freeNote],[data-act=freeLeft],[data-act=freePut],[data-act=freeBack]");if(!b)return;
  const a=b.dataset.act;
  if(a==="freeNote"||a==="freeLeft"){if(!$("#pickSheet").hidden){slotK=pickKey;$("#pickSheet").hidden=true;}if(!slotK)return;slotFree=a==="freeNote"?"note":"left";renderSlotSheet();$("#slotSheet").hidden=false;$("#slotSheet .sheet-in").scrollTop=0;return;}
  if(a==="freeBack"){slotFree=null;if(W()[slotK]||isPast(slotK))renderSlotSheet();else{$("#slotSheet").hidden=true;openPick(slotK,"main",true);}return;}
  const k=slotK;if(!k)return;
  const t=String(b.dataset.t!=null?b.dataset.t:(($("#freeQ")||{}).value||"").trim()||(slotFree==="left"?"du frigo":"")).slice(0,80);
  if(!t){toast("Écrivez ce que vous avez mangé, ou touchez un choix");return;}
  const f=slotFree==="note"?"note":"left",o=W()[k]||{};
  W()[k]=Object.assign({},o,{[f]:t,keep:true,n:o.n||menu.people});["id","lock","noIng",f==="note"?"left":"note"].forEach(x=>delete W()[k][x]);
  slotFree=null;if(typeof clearSheetBack==="function")clearSheetBack();$("#slotSheet").hidden=true;slotK=null;render();saveMenu();toast(f==="note"?"✏️ "+t+" : noté":"🥡 Restes ("+t+") : rien à acheter");
});

(function(){
  const offered = new Set();
  function eligible(){
    const result=[];
    for(const day of selectedShopDates()) for(const [meal] of MEALS){
      const slot=day.wk[slotKey(day.dn,meal)];
      if(!slot||!slot.lock||!recipes[slot.id]||["Courses faites","Terminé"].includes(slot.mealState))continue;
      let keys=[];
      if(Array.isArray(slot.ingCustom)){
        for(const ing of slot.ingCustom){
          if(!ing.n||(slot.noIng||[]).includes(ing.key))continue;
          const match=String(customIngredientQuantity(ing.qt,slot)).trim().match(/^([\d.,\/ ]+)\s*(.*)$/);
          const unit=match?match[2].trim():"";
          keys.push(norm(ing.n)+"|"+toBase(match?match[1].trim():"",unit)[1]);
        }
      }else{
        for(const id of [slot.id,slot.entree,slot.dessert].filter(Boolean)){
          for(const ing of (recipes[id]?.ing||[])){
            if(!ing.n)continue;
            const key=norm(ing.n)+"|"+toBase(ing.q,ing.u)[1];
            if(!(slot.noIng||[]).includes(key))keys.push(key);
          }
        }
      }
      keys=[...new Set(keys)];
      if(!keys.length)continue; // Never automatically validate an empty recipe.
      const id=ymd(mondayOf(day.d))+"|"+slotKey(day.dn,meal);
      result.push({id,week:ymd(mondayOf(day.d)),slot:slotKey(day.dn,meal),name:recipes[slot.id].name,
        complete:keys.every(key=>!!(menu.checked||{})[key]||!!(menu.have||{})[key])});
    }
    return result;
  }
  // Called by finishTrip BEFORE checked items are cleared, then applied AFTER
  // the purchase is recorded. Shared by Carnet and Maisonnée's embedded iframe.
  window.maisonneeFinishEligibleMeals=()=>eligible().filter(x=>x.complete).map(x=>x.id);
  window.maisonneeApplyFinishedMeals=function(ids){
    let changed=0;
    for(const id of ids){
      const split=id.indexOf("|");if(split<0)continue;
      const week=id.slice(0,split),key=id.slice(split+1);
      const slot=(menu.weeks||{})[week]?.[key];
      if(!slot||!slot.lock||!recipes[slot.id]||["Courses faites","Terminé"].includes(slot.mealState))continue;
      slot.mealState="Courses faites";slot.keep=true;slot.lock=true;changed++;
    }
    return changed;
  };
  function offer(completed){
    const ids=completed.map(x=>x.id);
    const names=completed.map(x=>"• "+x.name).join("\n");
    const msg=completed.length===1?"Courses terminées pour ce repas ?\n\n"+names+"\n\nValider le statut « Courses faites » ?":
      "Courses terminées pour ces "+completed.length+" repas ?\n\n"+names+"\n\nValider le statut « Courses faites » pour tous ?";
    // The Carnet is a hidden iframe inside Maisonnée. Its parent must show the confirmation.
    if(window.parent!==window){window.parent.postMessage({type:"maisonnee-meals-shopping-complete",ids,msg},location.origin);return;}
    if(window.confirm(msg))window.maisonneeConfirmShoppingMeals(ids);
  }
  window.maisonneeConfirmShoppingMeals=function(ids){
    let changed=0;
    for(const x of eligible()){
      if(!ids.includes(x.id)||!x.complete)continue;
      const slot=(menu.weeks||{})[x.week]?.[x.slot];
      if(!slot||["Courses faites","Terminé"].includes(slot.mealState))continue;
      slot.mealState="Courses faites";slot.keep=true;slot.lock=true;changed++;
    }
    if(changed){render();saveMenu();toast(changed+" repas : courses faites");}
    return changed;
  };
  // Observe only explicit check actions, never day navigation or meal display.
  document.addEventListener("click",function(e){
    const btn=e.target.closest('[data-act="storeTick"]');
    if(!btn||!String(btn.dataset.s||"").startsWith("k:"))return;
    const before=new Map(eligible().map(x=>[x.id,x.complete]));
    setTimeout(()=>{
      const done=eligible().filter(x=>x.complete&&!before.get(x.id)&&!offered.has(x.id));
      if(!done.length)return;
      done.forEach(x=>offered.add(x.id));offer(done);
    },0);
  },true);
  document.addEventListener("change",function(e){
    const t=e.target;
    if(t.dataset.act!=="check"||!t.checked)return;
    // The change event runs before the original handler; compare after it completes.
    const before=new Map(eligible().map(x=>[x.id,x.complete]));
    setTimeout(()=>{const done=eligible().filter(x=>x.complete&&!before.get(x.id)&&!offered.has(x.id));
      if(done.length){done.forEach(x=>offered.add(x.id));offer(done);}
    },0);
  },true);
})();
